// Builds the Solar Day 3D scene into one offline HTML page, stored as a string in
// lib/solarScene.generated.ts and loaded by components/panchang/solar/SolarSceneView.tsx.
//
//   npm run build:solar-scene          rewrite the generated file
//   npm run build:solar-scene -- --check   fail if it is out of date
//
// The page holds: a tree-shaken three.js (only the classes the scene uses, plus the
// Water reflection), lib/solarGeometry.ts (the same Sun maths the screen uses), and
// scripts/solar-scene/stage.js + world.js. Nothing is fetched at run time.
import { createHash } from 'node:crypto';
import { readFileSync, writeFileSync } from 'node:fs';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';
import { build } from 'esbuild';

const here = dirname(fileURLToPath(import.meta.url));
const root = join(here, '..', '..');
const OUT = join(root, 'lib', 'solarScene.generated.ts');

const THREE_NAMES = [
  'AdditiveBlending', 'BackSide', 'BoxGeometry', 'BufferGeometry', 'CanvasTexture', 'CatmullRomCurve3', 'Color',
  'ColorManagement', 'ConeGeometry', 'CylinderGeometry', 'DirectionalLight', 'DoubleSide', 'ExtrudeGeometry',
  'Float32BufferAttribute', 'Fog', 'Group', 'HemisphereLight', 'InstancedMesh', 'LatheGeometry', 'Line',
  'LineDashedMaterial', 'Mesh', 'MeshBasicMaterial', 'MeshStandardMaterial', 'Object3D', 'PCFShadowMap', 'Path',
  'PerspectiveCamera', 'PlaneGeometry', 'PointLight', 'Points', 'PointsMaterial', 'RepeatWrapping', 'SRGBColorSpace',
  'Scene', 'ShaderMaterial', 'Shape', 'ShapeGeometry', 'SphereGeometry', 'Sprite', 'SpriteMaterial', 'TubeGeometry',
  'Vector2', 'Vector3', 'WebGLRenderer',
];

async function bundle(options) {
  const result = await build({ bundle: true, minify: true, format: 'iife', write: false, legalComments: 'inline', logLevel: 'silent', ...options });
  return result.outputFiles[0].text;
}

const safeScript = (js) => js.replace(/<\/script/gi, '<\\/script');

export async function buildSolarSceneSource() {
  const threeVersion = JSON.parse(readFileSync(join(root, 'node_modules', 'three', 'package.json'), 'utf8')).version;
  const threeJs = await bundle({
    stdin: {
      contents:
        `import { ${THREE_NAMES.join(', ')} } from 'three';\n` +
        `import { Water } from 'three/examples/jsm/objects/Water.js';\n` +
        `window.THREE = { ${THREE_NAMES.join(', ')}, Water };\n`,
      resolveDir: root,
      loader: 'js',
    },
  });
  const geometryJs = await bundle({ entryPoints: [join(root, 'lib', 'solarGeometry.ts')], globalName: 'SolarGeometry' });
  const stage = readFileSync(join(here, 'stage.js'), 'utf8');
  if (!stage.includes('/*WORLD*/')) throw new Error('stage.js lost its /*WORLD*/ marker');
  const stageJs = stage.replace('/*WORLD*/', () => readFileSync(join(here, 'world.js'), 'utf8'));

  const html = `<!doctype html><html><head><meta charset="utf-8">
<meta name="viewport" content="width=device-width,initial-scale=1,maximum-scale=1,user-scalable=no">
<style>html,body{margin:0;height:100%;overflow:hidden;background:#0B1022;-webkit-user-select:none;user-select:none;-webkit-touch-callout:none}
#stage{position:fixed;inset:0;touch-action:none}#stage canvas{display:block;width:100%;height:100%}
#labels{position:absolute;inset:0;pointer-events:none}
.lab{position:absolute;left:0;top:0;padding:4px 12px;border-radius:999px;background:rgba(255,253,249,.88);color:#3E2A1F;font:600 14px/1.3 -apple-system,system-ui,Roboto,sans-serif;white-space:nowrap}</style>
</head><body><div id="stage" aria-hidden="true"><div id="labels"></div></div>
<script>${safeScript(threeJs)}</script>
<script>${safeScript(geometryJs)}</script>
<script>${safeScript(stageJs)}</script>
</body></html>`;

  const version = createHash('sha256').update(html).digest('hex').slice(0, 16);
  return (
    '// GENERATED by scripts/solar-scene/build.mjs. Do not edit: change the sources and run\n' +
    '// `npm run build:solar-scene`. Contains three.js ' + threeVersion + ' (MIT, licence kept inline below).\n' +
    `export const SOLAR_SCENE_VERSION = '${version}';\n` +
    `export const SOLAR_SCENE_HTML: string = ${JSON.stringify(html)};\n`
  );
}

if (process.argv[1] && fileURLToPath(import.meta.url) === process.argv[1]) {
  const source = await buildSolarSceneSource();
  if (process.argv.includes('--check')) {
    let current = '';
    try { current = readFileSync(OUT, 'utf8'); } catch { current = ''; } // a missing file is out of date
    if (current !== source) {
      console.error('lib/solarScene.generated.ts is out of date: run npm run build:solar-scene');
      process.exit(1);
    }
    process.stdout.write('solar scene up to date\n');
  } else {
    writeFileSync(OUT, source);
    process.stdout.write(`wrote ${OUT} (${source.length} bytes)\n`);
  }
}
